"""
Research sub page: Model-Driven Software Engineering (research-mde.html) — part 1 of the article series.
Introduces models, DSLs and generators, then whole applications from one model (MontiGem, CD2GUI), and ends with
the MaCoCo case study. Imported by build.py; figures and interactive demos in mde_figs.py (+ mde_levels.py,
mde_map.py), their behaviour in assets/mde.js, article-specific styles in assets/mde.css.

Three chapters (h2): models and languages · from model to code · whole applications from one model.
One running example throughout: a small library (Book, Member, Loan). Concept first, case study after; at most
about one citation per paragraph of running text (_build/STYLE.md).
"""
from ai4se import T, cite, ref, _link, definition, curious
from mde_figs import (HB, hero_mde, fig_intro, fig_inside, fig_backend, fig_maps, fig_classdiagram, fig_aspects,
                      demo_mailmerge, fig_generator, fig_evolution, fig_retrofit, fig_three_languages, fig_chain,
                      demo_syntax, demo_top, demo_files, demo_cd2gui, mapping_table, example_text)
from project_content import stats
import article_common

NL = "\n"
FILE = "research-mde.html"

# literature, in the module's own numbering (article_common.page() renumbers by first citation)
DEF, STA, DSLW, GEN, MCW = 1, 2, 3, 4, 5
GRE, FDSL, LC, GG, BOX, KOR = 7, 8, 9, 10, 11, 12
MCD = "https://monticore.github.io/monticore/docs/Languages/"
DJ = "https://docs.djangoproject.com/en/stable/ref/contrib/admin/"
RAILS = "https://guides.rubyonrails.org/command_line.html"
PRISMA = "https://www.prisma.io/docs/orm/prisma-migrate/workflows/customizing-migrations"
REFS = [
    _link("SE@RWTH: Definitions around Modeling.", "https://www.se-rwth.de/essay/Model-Definitions/"),
    "H. Stachowiak: Allgemeine Modelltheorie. Springer (1973).",
    _link("SE@RWTH: Domain-Specific Languages.", "https://www.se-rwth.de/research/Domain-Specific-Languages/"),
    _link("SE@RWTH: Generative Software Engineering.", "https://www.se-rwth.de/research/Generative-SE/"),
    _link("SE@RWTH: MontiCore.", "https://www.se-rwth.de/research/MontiCore/"),
    _link("K. Hölldobler, O. Kautz, B. Rumpe: MontiCore Language Workbench and Library Handbook, Edition 2021. Aachener Informatik-Berichte SE 48, Shaker (2021).", "https://www.monticore.de/handbook.pdf"),
    _link("T. Greifenberg et al.: A Comparison of Mechanisms for Integrating Handwritten and Generated Code for Object-Oriented Programming Languages. MODELSWARD (2015).", "https://arxiv.org/abs/1509.04498"),
    _link("M. Fowler: Domain-Specific Languages.", "https://martinfowler.com/dsl.html"),
    _link("B. Rumpe, J. Michael: Low Code (essay, 2024).", "https://www.se-rwth.de/essay/Low-Code/"),
    _link("M. Fowler: Generation Gap (DSL pattern catalogue).", "https://martinfowler.com/dslCatalog/generationGap.html"),
    "G. E. P. Box, N. R. Draper: Empirical Model-Building and Response Surfaces. Wiley (1987), p. 424.",
    "A. Korzybski: Science and Sanity. International Non-Aristotelian Library (1933).",
]
assert "Handbook" in REFS[HB - 1] and "Generation Gap" in REFS[GG - 1]
OWN = ["Net24", "BGK+24", "GMN+20", "GMNR21", "DGM+21", "MNN+22", "GLM+24", "NMR24", "BNR+25"]

GPT = {                         # Lukas's assistants; this article links only the first (dt.py uses gpt())
    "cd4a": ("CD4A Class Diagram Creator", "https://chatgpt.com/g/g-sRnmDgQvW-cd4a-class-diagram-creator"),
    "gui": ("GUI-DSL2 Model Creator", "https://chatgpt.com/g/g-OOGsSd6sA-gui-dsl2-model-creator"),
    "sysml": ("SysML v2 Model Creator", "https://chatgpt.com/g/g-3DkGCDlNM-sysml-v2-model-creator"),
    "mc": ("MontiCore Expert", "https://chatgpt.com/g/g-Pgayc5wzx-monticore-expert"),
}
CD4A_GPT = GPT["cd4a"]


def gpt(key, what):
    n, u = GPT[key]
    return (n, u, what)
DEMO = "https://montigem.demos.se.rwth-aachen.de/"


def tries(lang, items):
    """Links to try something: (name, url, T(what))."""
    return '<ul class="tries">' + "".join(f'<li><a href="{u}" target="_blank" rel="noopener">{n} ↗</a><span class="mono faint">{d[lang]}</span></li>' for n, u, d in items) + "</ul>"


def mono_box(lang, text, extra):
    """A curious box's body for this language only: the text T() plus figures or links (html)."""
    return {lang: text[lang] + extra}


def MC_LINKS(lang):
    return tries(lang, [(T("MontiCore handbook (PDF)", "MontiCore-Handbuch (PDF)")[lang], "https://www.monticore.de/handbook.pdf", T("the reference, free", "die Referenz, frei verfügbar")),
                        ("monticore.github.io", "https://monticore.github.io/monticore/", T("documentation, the languages CD4A and OCL", "Dokumentation, die Sprachen CD4A und OCL"))])


def body(lang):
    L = lambda x: x[lang]
    S = []          # (id, level, heading, html): 2 = numbered chapter, 3 = sub chapter, 1 = closing, 0 = intro
    S.append(("intro", 0, None, L(T(
        """<p>You have modelled before — maybe without calling it that. A spreadsheet formula describes a calculation that the spreadsheet carries out. An SQL <code>CREATE TABLE</code> describes data that the database then stores. A JSON schema describes a form that a library then draws. Each time you wrote down <i>what</i> you want in a small, specialised language, and a machine turned it into behaviour. If you have used Power Apps, a form builder or an OpenAPI code generator, you have used model-driven tools.</p>""",
        """<p>Sie haben schon modelliert — vielleicht ohne es so zu nennen. Eine Tabellenkalkulationsformel beschreibt eine Rechnung, die die Tabelle ausführt. Ein SQL-<code>CREATE TABLE</code> beschreibt Daten, die die Datenbank dann speichert. Ein JSON-Schema beschreibt ein Formular, das eine Bibliothek dann zeichnet. Jedes Mal haben Sie in einer kleinen, spezialisierten Sprache aufgeschrieben, <i>was</i> Sie wollen, und eine Maschine hat daraus Verhalten gemacht. Wer Power Apps, einen Formular-Baukasten oder einen OpenAPI-Codegenerator benutzt hat, hat modellgetriebene Werkzeuge benutzt.</p>"""))
        + f'<blockquote class="epigraph"><p>{L(T("“A model is an abstraction of an original made and used for a purpose.”", "„Ein Modell ist eine Abstraktion eines Originals, gemacht und genutzt für einen Zweck.“"))}</p><footer class="mono">{L(T("after Herbert Stachowiak, 1973", "nach Herbert Stachowiak, 1973"))} · {cite("DGM+21")}</footer></blockquote>'
        + L(T("""<p>Model-driven software engineering makes this the method: the important decisions about a system are written down as models, and generators turn the models into code — again and again, whenever the models change. This article explains the three building blocks — <i>models</i>, the <i>languages</i> they are written in, and the <i>generators</i> that read them — and then shows how far they carry: one class diagram becomes a running, data-centric web application with database, server and pages — a start that grows with its requirements instead of being thrown away. One small example runs through all of it: a library that lends books to its members.</p>""",
              """<p>Modellgetriebene Softwareentwicklung macht daraus die Methode: Die wichtigen Entscheidungen über ein System werden als Modelle aufgeschrieben, und Generatoren machen aus den Modellen Code — immer wieder, sobald sich die Modelle ändern. Dieser Artikel erklärt die drei Bausteine — <i>Modelle</i>, die <i>Sprachen</i>, in denen sie geschrieben sind, und die <i>Generatoren</i>, die sie lesen — und zeigt dann, wie weit sie tragen: Aus einem Klassendiagramm wird eine laufende, datenzentrierte Webanwendung mit Datenbank, Server und Seiten — ein Anfang, der mit seinen Anforderungen wächst, statt weggeworfen zu werden. Ein kleines Beispiel zieht sich durch alles: eine Bibliothek, die Bücher an ihre Mitglieder verleiht.</p>"""))
        + fig_intro(lang)))

    # ---------------- 01 Models and languages ----------------
    S.append(("models", 2, T("Models and languages", "Modelle und Sprachen"), L(T(
        "<p>Before anything can be generated, something has to be written down — and written down in a way a machine can read. This chapter is about the <i>what</i>: models, and the languages they are written in.</p>",
        "<p>Bevor etwas generiert werden kann, muss etwas aufgeschrieben werden — und zwar so, dass eine Maschine es lesen kann. Dieses Kapitel handelt vom <i>Was</i>: von Modellen und den Sprachen, in denen sie geschrieben sind.</p>"))))
    S.append(("model", 3, T("What is a model?", "Was ist ein Modell?"),
        L(T(f"""<p>A model <i>depicts</i> something, it <i>leaves things out</i>, and it <i>serves a purpose</i>. Herbert Stachowiak named these three features in 1973 — mapping, reduction and pragmatism — and they are still the best test for any model {ref(STA)}. A metro map is a model of a city: every dot stands for a real station (mapping), streets and hills are gone (reduction), and what remains is exactly what you need to get across town (purpose). A hiking map of the same city keeps the hills and drops the stations. Neither is “more correct” — each is good for something else.</p>""",
              f"""<p>Ein Modell <i>bildet</i> etwas <i>ab</i>, es <i>lässt etwas weg</i>, und es <i>dient einem Zweck</i>. Herbert Stachowiak hat diese drei Merkmale 1973 benannt — Abbildung, Verkürzung und Pragmatik —, und sie sind bis heute der beste Test für jedes Modell {ref(STA)}. Ein Liniennetzplan ist ein Modell einer Stadt: Jeder Punkt steht für eine echte Haltestelle (Abbildung), Straßen und Hügel fehlen (Verkürzung), und was bleibt, ist genau das, was man braucht, um durch die Stadt zu kommen (Zweck). Eine Wanderkarte derselben Stadt behält die Hügel und lässt die Haltestellen weg. Keine ist „richtiger“ — jede taugt für etwas anderes.</p>"""))
        + fig_maps(lang)
        + L(T("<p>So the useful question about a model is never “is it complete?” but “what is it for?”. In software, the original can be something that exists — a business process, an existing database — or something that is still to be built: the model of a system describes it before it is there.</p>",
              "<p>Die nützliche Frage an ein Modell ist deshalb nie „Ist es vollständig?“, sondern „Wofür ist es da?“. In der Software kann das Original etwas sein, das existiert — ein Geschäftsprozess, eine bestehende Datenbank — oder etwas, das erst gebaut werden soll: Das Modell eines Systems beschreibt es, bevor es da ist.</p>"))
        + definition(T("Model", "Modell"), T(f"A model describes some original, real system or entity that exists or is intended to exist in the future. A model is an abstraction of the original. A model has a purpose with respect to the original. {ref(DEF)}",
                                              f"Ein Modell beschreibt ein Original, ein reales System oder eine Entität, die existiert oder künftig existieren soll. Ein Modell ist eine Abstraktion des Originals. Ein Modell hat einen Zweck in Bezug auf das Original. {ref(DEF)}"), lang)
        + curious(lang, T(f"""<ul class="pts"><li><b>Descriptive or prescriptive.</b> A model can describe what is (an analysis of today’s process) or prescribe what shall be (the design of tomorrow’s system). Prescriptive models are the usual input for generating an implementation; descriptive ones can still be turned into reports, visualisations or documentation.</li><li><b>Explicit or programmed.</b> A text or diagram model is explicit; a model can also be implicit, encoded in a program — every program contains one.</li><li><b>Model-based or model-driven.</b> In model-<i>based</i> development, models support some activities; in model-<i>driven</i> development, they drive the process and are the primary artefacts.</li><li><b>Many models.</b> Every model covers only some aspects of its original, so a system is described by a set of models.</li><li><b>Two famous one-liners</b> say the same as Stachowiak’s reduction: “all models are wrong, but some are useful” (George Box) {ref(BOX)}, and “a map is not the territory it represents” (Alfred Korzybski) {ref(KOR)}.</li></ul>""",
                          f"""<ul class="pts"><li><b>Beschreibend oder vorschreibend.</b> Ein Modell kann beschreiben, was ist (eine Analyse des heutigen Prozesses), oder vorschreiben, was sein soll (der Entwurf des Systems von morgen). Vorschreibende Modelle sind die übliche Eingabe, wenn eine Implementierung generiert wird; aus beschreibenden lassen sich trotzdem Berichte, Visualisierungen oder Dokumentation erzeugen.</li><li><b>Explizit oder programmiert.</b> Ein Text- oder Diagrammmodell ist explizit; ein Modell kann auch implizit in einem Programm stecken — jedes Programm enthält eines.</li><li><b>Modellbasiert oder modellgetrieben.</b> In der modell<i>basierten</i> Entwicklung unterstützen Modelle einzelne Tätigkeiten; in der modell<i>getriebenen</i> Entwicklung treiben sie den Prozess, Modelle sind die primären Artefakte.</li><li><b>Viele Modelle.</b> Jedes Modell erfasst nur einige Aspekte seines Originals; ein System wird deshalb durch eine Menge von Modellen beschrieben.</li><li><b>Zwei berühmte Einzeiler</b> sagen dasselbe wie Stachowiaks Verkürzung: „Alle Modelle sind falsch, aber manche sind nützlich“ (George Box) {ref(BOX)} und „Die Karte ist nicht das Gebiet, das sie darstellt“ (Alfred Korzybski) {ref(KOR)}.</li></ul>"""),
                  T("Kinds of models", "Arten von Modellen"))))
    S.append(("classdiagram", 3, T("Reading a class diagram in 60 seconds", "Klassendiagramme in 60 Sekunden lesen"),
        L(T("""<p>Most of this article works with one kind of model: the class diagram. It describes the kinds of things in a domain and how they relate. A <i>class</i> is a kind of thing (Book, Member); an <i>attribute</i> is a field every such thing has (a title, a number of pages). A line between two classes is an <i>association</i>: the two belong together. The numbers at its ends say how many — <code>1</code> exactly one, <code>*</code> any number. That is enough to read the running example of this article: a small library that lends books to its members.</p>""",
              """<p>Der Großteil dieses Artikels arbeitet mit einer Art von Modell: dem Klassendiagramm. Es beschreibt die Arten von Dingen in einer Domäne und wie sie zusammenhängen. Eine <i>Klasse</i> ist eine Art von Ding (Book, Member); ein <i>Attribut</i> ist ein Feld, das jedes solche Ding hat (ein Titel, eine Seitenzahl). Eine Linie zwischen zwei Klassen ist eine <i>Assoziation</i>: Die beiden gehören zusammen. Die Zahlen an ihren Enden sagen, wie viele — <code>1</code> genau eins, <code>*</code> beliebig viele. Das reicht, um das laufende Beispiel dieses Artikels zu lesen: eine kleine Bibliothek, die Bücher an ihre Mitglieder verleiht.</p>"""))
        + fig_classdiagram(lang)
        + L(T(f"""<p>The same model can be written as text. <a href="{MCD}" target="_blank" rel="noopener">CD4A</a> is MontiCore’s textual language for class diagrams:</p>""",
              f"""<p>Dasselbe Modell lässt sich als Text schreiben. <a href="{MCD}" target="_blank" rel="noopener">CD4A</a> ist MontiCores textuelle Sprache für Klassendiagramme:</p>"""))
        + f'<pre class="mono art-pre">{example_text()}</pre>'
        + L(T("<p>You do not have to write such models by hand. My assistant turns a sentence about your domain into a CD4A class diagram:</p>", "<p>Solche Modelle müssen Sie nicht von Hand schreiben. Mein Assistent macht aus einem Satz über Ihre Domäne ein CD4A-Klassendiagramm:</p>"))
        + tries(lang, [(*CD4A_GPT, T("describe your domain in one sentence, get a class diagram", "Domäne in einem Satz beschreiben, Klassendiagramm erhalten"))])))
    S.append(("dsl", 3, T("Languages for models: DSL vs. general-purpose", "Sprachen für Modelle: DSL vs. Allzwecksprache"),
        L(T(f"""<p>Java, Python or C# can express any program — they are <i>general-purpose languages</i>. A <i>domain-specific language</i> (DSL) trades that generality for closeness to one domain: it offers the domain’s concepts directly and leaves out much else, but says what it can briefly and in the domain’s own terms. You already know several: SQL for data, HTML for documents, CSS for layout, spreadsheet formulas for calculations, regular expressions for text patterns. A DSL can say less than Java, but what it can say, it says in a few lines — and in words that people outside IT already use {ref(DSLW)}.</p>
<p>Real systems are described by several small languages, one per aspect: one for the data, one for the pages, one for the rules, one for who may see what. Each stays simple because it does one job — and they fit together because they refer to the same names.</p>""",
              f"""<p>Java, Python oder C# können jedes Programm ausdrücken — sie sind <i>Allzwecksprachen</i>. Eine <i>domänenspezifische Sprache</i> (DSL) tauscht diese Allgemeinheit gegen Nähe zu einer Domäne: Sie bietet deren Begriffe direkt an und lässt vieles andere weg, sagt aber, was sie sagen kann, kurz und in den Begriffen der Domäne. Einige kennen Sie schon: SQL für Daten, HTML für Dokumente, CSS für Layout, Tabellenformeln für Berechnungen, reguläre Ausdrücke für Textmuster. Eine DSL kann weniger sagen als Java, aber was sie sagen kann, sagt sie in wenigen Zeilen — und in Worten, die auch Menschen außerhalb der IT schon benutzen {ref(DSLW)}.</p>
<p>Echte Systeme werden mit mehreren kleinen Sprachen beschrieben, je eine pro Aspekt: eine für die Daten, eine für die Seiten, eine für die Regeln, eine dafür, wer was sehen darf. Jede bleibt einfach, weil sie eine Aufgabe hat — und sie passen zusammen, weil sie auf dieselben Namen verweisen.</p>"""))
        + fig_aspects(lang)
        + curious(lang, T(f"""<ul class="pts"><li><b>Internal or external.</b> An internal DSL lives inside a host language (a fluent Java API); an external DSL has its own syntax and its own parser {ref(FDSL)}. The languages in this article are external.</li><li><b>Text or graphics.</b> Experts are often faster in text. Yet the end users in one project preferred the graphical class diagram once it had more than 120 classes {cite('BGK+24')}. Good tools offer both views of one model.</li><li><b>What a language consists of.</b> Its syntax (how models look), its semantics (what they mean) and its pragmatics (how to use them for their purpose).</li></ul>""",
                          f"""<ul class="pts"><li><b>Intern oder extern.</b> Eine interne DSL lebt in einer Wirtssprache (eine flüssige Java-API); eine externe DSL hat eine eigene Syntax und einen eigenen Parser {ref(FDSL)}. Die Sprachen in diesem Artikel sind extern.</li><li><b>Text oder Grafik.</b> Fachleute sind im Text oft schneller. Die Endnutzer eines Projekts bevorzugten trotzdem das grafische Klassendiagramm, sobald es mehr als 120 Klassen hatte {cite('BGK+24')}. Gute Werkzeuge bieten beide Sichten auf ein Modell.</li><li><b>Woraus eine Sprache besteht.</b> Aus ihrer Syntax (wie Modelle aussehen), ihrer Semantik (was sie bedeuten) und ihrer Pragmatik (wie man sie für ihren Zweck einsetzt).</li></ul>"""),
                  T("Kinds of DSLs", "Arten von DSLs"))))
    S.append(("syntax", 3, T("The picture is not the model", "Das Bild ist nicht das Modell"),
        L(T("""<p>Is the model the text, or the diagram? Neither. Text and diagram are two concrete ways to <i>show</i> the model. Tools work on its <i>abstract syntax</i>: the model’s elements and their relationships, held as a data structure. In MontiCore, that structure is a tree — the <i>abstract syntax tree</i> (AST) — which a parser builds from the text and symbol resolution then links across names; other frameworks keep a graph of objects that conforms to a <a href="#metamodel">metamodel</a>. A diagram editor shows the same structure as boxes and lines; typing and drawing edit the same model. This is why a generator never cares whether you typed or drew.</p>""",
              """<p>Ist das Modell der Text oder das Diagramm? Weder noch. Text und Diagramm sind zwei konkrete Arten, das Modell zu <i>zeigen</i>. Werkzeuge arbeiten auf seiner <i>abstrakten Syntax</i>: den Elementen des Modells und ihren Beziehungen, gehalten als Datenstruktur. In MontiCore ist diese Struktur ein Baum — der <i>abstrakte Syntaxbaum</i> (AST) —, den ein Parser aus dem Text baut und die Symbolauflösung dann über Namen verknüpft; andere Frameworks halten einen Objektgraphen, der zu einem <a href="#metamodel">Metamodell</a> konform ist. Ein Diagrammeditor zeigt dieselbe Struktur als Kästen und Linien; Tippen und Zeichnen ändern dasselbe Modell. Deshalb ist es einem Generator egal, ob Sie getippt oder gezeichnet haben.</p>"""))
        + L(T(f"""<p>It is also why checking happens in steps. First: is the text <i>readable</i> at all — does the parser accept it? Second: are all <i>names known</i> — does every <code>Book</code> that is mentioned exist? Third: are the <i>rules kept</i> — for example, no two attributes with the same name? The grammar only answers the first question. The others are <i>context conditions</i>: rules every valid model must obey, written by hand against the tree.</p>""",
              f"""<p>Deshalb wird auch in Stufen geprüft. Erstens: Ist der Text überhaupt <i>lesbar</i> — nimmt der Parser ihn an? Zweitens: Sind alle <i>Namen bekannt</i> — gibt es jedes erwähnte <code>Book</code>? Drittens: Sind die <i>Regeln eingehalten</i> — zum Beispiel keine zwei Attribute mit demselben Namen? Die Grammatik beantwortet nur die erste Frage. Der Rest sind <i>Kontextbedingungen</i>: Regeln, die jedes gültige Modell einhalten muss, von Hand gegen den Baum geschrieben.</p>"""))
        + demo_syntax(lang)
        + L(T("""<p>Names are also how models refer to each other. A page model says <code>Book</code> and means the class in the data model — through the <i>symbol table</i>, an index of all named elements, even across files and languages. The page model holds a reference, not a copy: if <code>Book</code> is renamed or removed, the tools report the reference as unresolved instead of silently keeping an outdated duplicate. And grammars can do more than check: they can also constrain what an LLM writes, token by token — see <a href="research-ai4se.html#masking">grammar masking in part 2</a>.</p>""",
              """<p>Über Namen verweisen Modelle auch aufeinander. Ein Seitenmodell sagt <code>Book</code> und meint die Klasse im Datenmodell — über die <i>Symboltabelle</i>, ein Verzeichnis aller benannten Elemente, auch über Dateien und Sprachen hinweg. Das Seitenmodell hält einen Verweis, keine Kopie: Wird <code>Book</code> umbenannt oder gelöscht, melden die Werkzeuge den Verweis als unaufgelöst, statt still eine veraltete Kopie zu behalten. Und Grammatiken können mehr als prüfen: Sie können auch einschränken, was ein LLM schreibt, Token für Token — siehe <a href="research-ai4se.html#masking">Grammar Masking in Teil 2</a>.</p>"""))
        + curious(lang, T(f"""<span id="metamodel"></span><p>A model conforms to its language, and the language is defined by a grammar (as in MontiCore) or by a <i>metamodel</i>, a model of the abstract syntax of a language. MontiCore derives such a description from every grammar internally, as a class diagram. Separate from this <i>conforms to</i> is the <i>instance of</i> of objects and classes: the object <code>anna : Member</code> is an instance of the class Member; the class diagram itself conforms to CD4A. And what a model <i>means</i> is a third question: its semantics, a mapping into a semantic domain.</p>""",
                          f"""<span id="metamodel"></span><p>Ein Modell ist konform zu seiner Sprache, und die Sprache ist durch eine Grammatik (wie in MontiCore) oder durch ein <i>Metamodell</i> definiert, ein Modell der abstrakten Syntax einer Sprache. MontiCore leitet aus jeder Grammatik intern eine solche Beschreibung ab, als Klassendiagramm. Davon zu trennen ist das <i>ist Instanz von</i> zwischen Objekten und Klassen: Das Objekt <code>anna : Member</code> ist eine Instanz der Klasse Member; das Klassendiagramm selbst ist konform zu CD4A. Und was ein Modell <i>bedeutet</i>, ist eine dritte Frage: seine Semantik, eine Abbildung in eine semantische Domäne.</p>"""),
                  T("Languages for languages", "Sprachen für Sprachen"))))

    # ---------------- 02 From model to code ----------------
    S.append(("generation", 2, T("From model to code", "Vom Modell zum Code"), L(T(
        "<p>Even without generation, models are useful: to communicate, to analyse, to validate a design before it is built. They start to <i>drive</i> development when a program reads them and systematically derives something from them: code, other models, tests, documentation. That program is a generator.</p>",
        "<p>Auch ohne Generierung sind Modelle nützlich: zum Verständigen, zum Analysieren, zum Prüfen eines Entwurfs, bevor er gebaut wird. Die Entwicklung <i>treiben</i> sie erst an, wenn ein Programm sie liest und systematisch etwas daraus ableitet: Code, andere Modelle, Tests, Dokumentation. Dieses Programm ist ein Generator.</p>"))))
    S.append(("generator", 3, T("What a generator does", "Was ein Generator tut"),
        L(T(f"""<span id="transformation"></span><p>Start with the problem. In a typical business application, the same data structure turns up again and again: as a database table, as a server class, as a transfer object, as a model in the browser, as a form. Writing these by hand is tedious and error-prone — and it is <i>schematic</i>: knowing the data structure, you could almost type the rest blindfolded. That is exactly what can be generated.</p>
<p>Most generators work like mail merge. A letter template has placeholders, and a list of addresses fills them, one letter per address. A code <i>template</i> is the target code with holes in it, and the model fills the holes:</p>""",
              f"""<span id="transformation"></span><p>Am Anfang steht das Problem. In einer typischen Geschäftsanwendung taucht dieselbe Datenstruktur immer wieder auf: als Datenbanktabelle, als Serverklasse, als Transferobjekt, als Modell im Browser, als Formular. Das alles von Hand zu schreiben ist mühsam und fehleranfällig — und es ist <i>schematisch</i>: Wer die Datenstruktur kennt, könnte den Rest fast blind tippen. Genau das lässt sich generieren.</p>
<p>Die meisten Generatoren arbeiten wie ein Serienbrief. Eine Briefvorlage hat Platzhalter, und eine Adressliste füllt sie, ein Brief je Adresse. Ein Code-<i>Template</i> ist der Zielcode mit Lücken, und das Modell füllt die Lücken:</p>"""))
        + demo_mailmerge(lang)
        + L(T("""<p>The model carries the <i>domain</i>, the templates carry the <i>technology</i>: swap the templates — and the runtime parts they rely on — and the same model can produce code for another platform. And one model line reaches every tier at once. Try it — add attributes to <code>Book</code>:</p>""",
              """<p>Das Modell trägt die <i>Domäne</i>, die Templates tragen die <i>Technik</i>: Tauscht man die Templates — und die Laufzeitteile, auf die sie bauen —, kann dasselbe Modell Code für eine andere Plattform erzeugen. Und eine Modellzeile erreicht jede Schicht auf einmal. Probieren Sie es — ergänzen Sie Attribute an <code>Book</code>:</p>"""))
        + demo_files(lang)
        + L(T("""<p>You may have used generators like this. Prisma derives database tables and a typed client from one schema file; OpenAPI Generator turns one API description into clients, servers and documentation. The generators in this article work the same way, with one difference that matters: they are not run once to get started, but again and again, with every change to the model.</p>
<p>A real generator does more than fill templates. It <i>reads</i> the model and checks it, <i>transforms</i> it into a structure closer to the target — adding, for example, an <code>id</code> nobody modelled — and only then <i>generates</i>. Step inside:</p>""",
              """<p>Vielleicht haben Sie solche Generatoren schon benutzt. Prisma leitet aus einer Schemadatei Datenbanktabellen und einen typisierten Client ab; OpenAPI Generator macht aus einer API-Beschreibung Clients, Server und Dokumentation. Die Generatoren in diesem Artikel arbeiten genauso, mit einem Unterschied, der zählt: Sie laufen nicht einmal zum Start, sondern immer wieder, bei jeder Änderung am Modell.</p>
<p>Ein echter Generator kann mehr als Templates füllen. Er <i>liest</i> das Modell und prüft es, <i>transformiert</i> es in eine Struktur, die näher am Ziel liegt — und ergänzt dabei etwa eine <code>id</code>, die niemand modelliert hat —, und erst dann <i>generiert</i> er. Ein Blick hinein:</p>"""))
        + fig_inside(lang)
        + L(T(f"""<p>And a generator adds things that were never in the model at all — login, the wiring of the database — on top of a hand-built <i>runtime environment</i>, the ready-made part the generated code plugs into {ref(GEN)}.</p>""",
              f"""<p>Und ein Generator fügt Dinge hinzu, die nie im Modell standen — Login, die Anbindung der Datenbank —, auf einer handgebauten <i>Laufzeitumgebung</i>, dem fertigen Teil, in den sich der generierte Code einsteckt {ref(GEN)}.</p>"""))
        + definition("Generator", T(f"Code generation is the process of translating a source model into artifacts of an executable language. {ref(DEF)}",
                                      f"Codegenerierung ist die Übersetzung eines Quellmodells in Artefakte einer ausführbaren Sprache. {ref(DEF)}"), lang)
        + curious(lang, T(f"""<ul class="pts"><li><b>Why an intermediate tree.</b> When the input and the output language are far apart, it pays to transform the input’s AST into one that fits the output first.</li><li><b>One model, several meanings.</b> The same model can be mapped differently: a state <code>Off</code> might become an enum constant, an integer, a subclass or a method. So the meaning has to be settled before a generator is built.</li><li><b>Configurable generators.</b> Templates can be replaced at hook points, and generators should be able to leave out what a project does not use — unused generated endpoints are a security issue {cite('BGK+24')}.</li></ul>""",
                          f"""<ul class="pts"><li><b>Warum ein Zwischenbaum.</b> Liegen Eingabe- und Ausgabesprache weit auseinander, lohnt es sich, den AST der Eingabe zuerst in einen zu transformieren, der zur Ausgabe passt.</li><li><b>Ein Modell, mehrere Bedeutungen.</b> Dasselbe Modell lässt sich verschieden abbilden: Ein Zustand <code>Off</code> kann eine Enum-Konstante, eine Ganzzahl, eine Unterklasse oder eine Methode werden. Deshalb muss die Bedeutung geklärt sein, bevor ein Generator gebaut wird.</li><li><b>Konfigurierbare Generatoren.</b> Templates lassen sich an Hook-Punkten ersetzen, und Generatoren sollten weglassen können, was ein Projekt nicht nutzt — ungenutzte generierte Endpunkte sind ein Sicherheitsrisiko {cite('BGK+24')}.</li></ul>"""),
                  T("Inside real generators", "In echten Generatoren"))
        + curious(lang, mono_box(lang, T(f"""<span id="monticore"></span><p>Where do the languages CD4A, GUI-DSL and OCL/P come from, with their parsers, symbol tables and checks? From MontiCore, a language workbench developed at RWTH Aachen since 2004 {ref(MCW)}. MontiCore builds the tools that read your models: from a grammar it generates the parser, the tree classes, the symbol table and the frame for the rule checks; the language engineer adds the rules, the tool builder the transformations and templates. Its strength is composition: languages are built from languages — the GUI-DSL refers to CD4A through symbols, OCL/P embeds an expression language. That is how MontiGem’s family of languages could grow without being rewritten.</p>""",
                          f"""<span id="monticore"></span><p>Woher kommen die Sprachen CD4A, GUI-DSL und OCL/P mit ihren Parsern, Symboltabellen und Prüfungen? Aus MontiCore, einer Language Workbench, die an der RWTH Aachen seit 2004 entwickelt wird {ref(MCW)}. MontiCore baut die Werkzeuge, die Ihre Modelle lesen: Aus einer Grammatik generiert es den Parser, die Baumklassen, die Symboltabelle und den Rahmen für die Regelprüfungen; die Sprachingenieurin ergänzt die Regeln, der Werkzeugbauer Transformationen und Templates. Seine Stärke ist Komposition: Sprachen werden aus Sprachen gebaut — die GUI-DSL verweist über Symbole auf CD4A, OCL/P bettet eine Ausdruckssprache ein. So konnte MontiGems Sprachfamilie wachsen, ohne neu geschrieben zu werden.</p>"""), fig_generator(lang) + MC_LINKS(lang)),
                  T("MontiCore, the tool that builds the tools", "MontiCore, das Werkzeug, das die Werkzeuge baut"))))
    S.append(("handwritten", 3, T("Generated and hand-written code", "Generierter und handgeschriebener Code"),
        L(T(f"""<p>Complete generation is rare: real systems mix generated and hand-written code — the business rule no model covers, the special screen, the connection to an old system. The rule that makes this work is simple: <i>never edit generated code</i>. The next generation run overwrites it. A one-off scaffold is still a useful start — but only a generator that can be run again keeps helping a system whose models keep changing {cite('DGM+21')}.</p>
<p>Instead, hand-written code <i>builds on</i> the generated code. MontiCore and MontiGem use the TOP mechanism for this: if a hand-written class <code>Loan</code> exists, the generator names its own class <code>LoanTOP</code>, and the hand-written class extends it. Everything else in the system keeps using the name <code>Loan</code> and gets the hand-written version.</p>""",
              f"""<p>Vollständige Generierung ist selten: Echte Systeme mischen generierten und handgeschriebenen Code — die Geschäftsregel, die kein Modell abdeckt, die besondere Maske, die Anbindung an ein Altsystem. Die Regel, die das möglich macht, ist einfach: <i>Generierten Code nie bearbeiten</i>. Der nächste Generierungslauf überschreibt ihn. Ein einmaliges Gerüst ist trotzdem ein brauchbarer Start — aber nur ein Generator, der wieder laufen kann, hilft einem System weiter, dessen Modelle sich weiter ändern {cite('DGM+21')}.</p>
<p>Stattdessen <i>baut</i> handgeschriebener Code auf dem generierten <i>auf</i>. MontiCore und MontiGem nutzen dafür den TOP-Mechanismus: Gibt es eine handgeschriebene Klasse <code>Loan</code>, nennt der Generator seine eigene Klasse <code>LoanTOP</code>, und die handgeschriebene Klasse erweitert sie. Der Rest des Systems benutzt weiter den Namen <code>Loan</code> und bekommt die handgeschriebene Fassung.</p>"""))
        + demo_top(lang)
        + L(T(f"""<p>The price is small but real: the generator has to look for hand-written files, so after adding or removing one you regenerate once. And the trick has a limit: page models are trees, not classes, so there is nothing to extend — how pages are customised instead is shown under <a href="#cd2gui">CD2GUI</a>. The lesson from five projects is plain: a code generator has to support hand-written extensions {cite('BGK+24')}.</p>""",
              f"""<p>Der Preis ist klein, aber real: Der Generator muss nach handgeschriebenen Dateien suchen, also generiert man nach dem Anlegen oder Löschen einer solchen Datei einmal neu. Und der Trick hat eine Grenze: Seitenmodelle sind Bäume, keine Klassen, es gibt also nichts zu erweitern — wie Seiten stattdessen angepasst werden, zeigt der Abschnitt zu <a href="#cd2gui">CD2GUI</a>. Die Lehre aus fünf Projekten ist eindeutig: Ein Codegenerator muss handgeschriebene Erweiterungen unterstützen {cite('BGK+24')}.</p>"""))
        + curious(lang, T(f"""<ul class="pts"><li><b>The general pattern.</b> TOP is a variant of the <i>Generation Gap</i> pattern: “separate generated code from non-generated code by inheritance”, first described by John Vlissides {ref(GG)}. C# partial classes solve the same problem without inheritance.</li><li><b>Other mechanisms.</b> Delegation, or “protected regions” inside generated files that the generator leaves alone — the last are fragile {ref(GRE)}.</li><li><b>Separate folders.</b> Hand-written and generated code live in separate directory trees. Many projects keep generated code out of version control and regenerate it in every build; others check it in to review what the generator changed — a choice of workflow, not a law.</li><li><b>Not round-trip engineering.</b> Code is never fed back into the model: the model stays the source, the code is always derived.</li></ul>""",
                          f"""<ul class="pts"><li><b>Das allgemeine Muster.</b> TOP ist eine Variante des Musters <i>Generation Gap</i>: generierten und nicht generierten Code durch Vererbung trennen, zuerst beschrieben von John Vlissides {ref(GG)}. Partielle Klassen in C# lösen dasselbe Problem ohne Vererbung.</li><li><b>Andere Mechanismen.</b> Delegation, oder „geschützte Bereiche“ in generierten Dateien, die der Generator in Ruhe lässt — Letztere sind fragil {ref(GRE)}.</li><li><b>Getrennte Ordner.</b> Handgeschriebener und generierter Code liegen in getrennten Verzeichnisbäumen. Viele Projekte halten generierten Code aus der Versionskontrolle heraus und generieren ihn bei jedem Build neu; andere checken ihn ein, um zu sehen, was der Generator geändert hat — eine Frage des Arbeitsablaufs, kein Gesetz.</li><li><b>Kein Round-Trip-Engineering.</b> Code fließt nie ins Modell zurück: Das Modell bleibt die Quelle, der Code wird immer abgeleitet.</li></ul>"""),
                  T("Generation Gap and other mechanisms", "Generation Gap und andere Mechanismen"))))
    S.append(("evolution", 3, T("When the model changes", "Wenn sich das Modell ändert"),
        L(T("""<p>Regenerating is safe for the <i>code</i>. But a running system also has <i>data</i>, and that data was stored in the shape of the old model. When the model changes, the code is simply regenerated, but the data already stored may have to be converted:</p>""",
              """<p>Neu generieren ist für den <i>Code</i> sicher. Ein laufendes System hat aber auch <i>Daten</i>, und die wurden in der Form des alten Modells gespeichert. Ändert sich das Modell, wird der Code einfach neu generiert, aber die schon gespeicherten Daten müssen womöglich umgewandelt werden:</p>"""))
        + fig_evolution(lang)
        + L(T(f"""<p>Database tools draw the same line: <a href="{PRISMA}" target="_blank" rel="noopener">Prisma</a> generates a migration for the new structure, and filling the new columns from the old ones is a step you write into that migration yourself. So plan models for growth: additions are usually easier to absorb than changes to what is already there — though even a new attribute needs a migration when the records already stored must have a value for it.</p>""",
              f"""<p>Datenbankwerkzeuge ziehen dieselbe Linie: <a href="{PRISMA}" target="_blank" rel="noopener">Prisma</a> generiert eine Migration für die neue Struktur, und die neuen Spalten aus den alten zu füllen, ist ein Schritt, den man selbst in diese Migration schreibt. Modelle also auf Wachstum anlegen: Ergänzungen lassen sich meist leichter auffangen als Änderungen an Bestehendem — doch auch ein neues Attribut braucht eine Migration, wenn die schon gespeicherten Datensätze einen Wert dafür haben müssen.</p>"""))
        + curious(lang, T(f"""<p>Practice confirms the rule of thumb: in MaCoCo, additions to the models took less time than changes, which also touched hand-written code and, in the data model, required data migrations in the running application {cite('DGM+21')}. Research goes one step further: comparing two versions of a model not line by line but by meaning — what can the new model express that the old one could not? That is what my work on the evolution of domain models looks at {cite('BNR+25')}.</p>""",
                          f"""<p>Die Praxis bestätigt die Faustregel: In MaCoCo kosteten Ergänzungen an den Modellen weniger Zeit als Änderungen, die auch handgeschriebenen Code berührten und im Datenmodell Datenmigrationen in der laufenden Anwendung nötig machten {cite('DGM+21')}. Die Forschung geht einen Schritt weiter: zwei Versionen eines Modells nicht Zeile für Zeile, sondern nach ihrer Bedeutung zu vergleichen — was kann das neue Modell ausdrücken, was das alte nicht konnte? Damit befasst sich meine Arbeit zur Evolution von Domänenmodellen {cite('BNR+25')}.</p>"""),
                  T("Model evolution in practice and research", "Modellevolution in Praxis und Forschung"))))

    # ---------------- 03 Whole applications from one model ----------------
    S.append(("montigem", 2, T("Whole applications from one model", "Ganze Anwendungen aus einem Modell"), L(T(
        "<p>Model-driven techniques are used far beyond business software — in embedded and cyber-physical systems, software product lines, system analysis. From here on, this article stays with data-centric web applications, where the ideas show most clearly, and with one toolchain, MontiCore and MontiGem. The pieces come together: a generator that turns a class diagram into a web application, a language for its pages, a transformation that derives the pages by itself — and what all of this has to do with low-code and AI. The chapter ends with a case study from practice and what the approach costs.</p>",
        "<p>Modellgetriebene Techniken werden weit über Geschäftssoftware hinaus eingesetzt — in eingebetteten und cyber-physischen Systemen, Software-Produktlinien, der Systemanalyse. Ab hier bleibt dieser Artikel bei datenzentrierten Webanwendungen, an denen sich die Ideen am klarsten zeigen, und bei einer Werkzeugkette, MontiCore und MontiGem. Die Teile fügen sich zusammen: ein Generator, der aus einem Klassendiagramm eine Webanwendung macht, eine Sprache für ihre Seiten, eine Transformation, die die Seiten selbst ableitet — und was das alles mit Low-Code und KI zu tun hat. Am Ende des Kapitels stehen eine Fallstudie aus der Praxis und das, was der Ansatz kostet.</p>"))))
    S.append(("whygen", 3, T("Why business applications repeat themselves", "Warum sich Geschäftsanwendungen wiederholen"),
        L(T(f"""<span id="architecture"></span><p>Think of the software that administrations run on: finances, staff, inventory, loans. Lists, forms and detail pages over a central database — and at their core always the same four operations: create, read, update and delete, CRUD for short. Such <i>information systems</i> are big, but their structure repeats with every class of the data model. You have probably seen this used: <a href="{DJ}" target="_blank" rel="noopener">Django’s admin</a> reads the models of an application and builds management pages from them, though it is meant as an internal tool, not as the application itself; <a href="{RAILS}" target="_blank" rel="noopener">Rails’ scaffold generator</a> writes model, controller, views and a database migration for a resource in one command — once, as a starting point to edit by hand.</p>""",
              f"""<span id="architecture"></span><p>Denken Sie an die Software, mit der Verwaltungen arbeiten: Finanzen, Personal, Inventar, Ausleihen. Listen, Formulare und Detailseiten über einer zentralen Datenbank — und im Kern immer dieselben vier Operationen: anlegen, lesen, ändern und löschen, kurz CRUD. Solche <i>Informationssysteme</i> sind groß, aber ihre Struktur wiederholt sich mit jeder Klasse des Datenmodells. Wahrscheinlich haben Sie das schon genutzt gesehen: <a href="{DJ}" target="_blank" rel="noopener">Djangos Admin</a> liest die Modelle einer Anwendung und baut daraus Verwaltungsseiten, gedacht allerdings als internes Werkzeug, nicht als die Anwendung selbst; der <a href="{RAILS}" target="_blank" rel="noopener">Scaffold-Generator von Rails</a> schreibt mit einem Befehl Modell, Controller, Views und eine Datenbankmigration für eine Ressource — einmal, als Startpunkt zum Weiterbearbeiten von Hand.</p>"""))
        + L(T(f"""<p>MontiGem — the <i>MontiCore-based Generator for Enterprise Management</i> — goes the whole way. The class diagram is the only mandatory model {cite('GMN+20')}; page models, rules and access tags can be added. From them it generates a complete, data-centric three-tier application — a database with its access layer, a Java server, an Angular/TypeScript front end — and it keeps regenerating it as the models change, with hand-written code kept apart as above. Because all tiers come from one model, their interfaces fit together by construction. What a class diagram does not say — business rules, workflows, connections to other systems — is added through further models or hand-written extensions.</p>""",
              f"""<p>MontiGem — der <i>MontiCore-based Generator for Enterprise Management</i> — geht den ganzen Weg. Das Klassendiagramm ist das einzige Pflichtmodell {cite('GMN+20')}; Seitenmodelle, Regeln und Zugriffs-Tags können hinzukommen. Daraus generiert es eine vollständige, datenzentrierte dreischichtige Anwendung — eine Datenbank mit Zugriffsschicht, einen Java-Server, ein Angular/TypeScript-Frontend — und generiert sie immer wieder neu, wenn sich die Modelle ändern, mit getrennt gehaltenem handgeschriebenem Code wie oben. Weil alle Schichten aus einem Modell stammen, passen ihre Schnittstellen per Konstruktion zusammen. Was ein Klassendiagramm nicht sagt — Geschäftsregeln, Abläufe, Anbindungen an andere Systeme —, kommt über weitere Modelle oder handgeschriebene Erweiterungen hinzu.</p>"""))
        + curious(lang, mono_box(lang, T("<p>The generator from the start of the article, at full detail: this is what MontiGem’s back-end generator looks like inside.</p>",
                                         "<p>Der Generator vom Anfang des Artikels, in voller Detailtiefe: So sieht MontiGems Backend-Generator von innen aus.</p>"), fig_backend(lang)),
                  T("MontiGem’s back-end generator", "MontiGems Backend-Generator"))))
    S.append(("guidsl", 3, T("Describing pages: the GUI-DSL", "Seiten beschreiben: die GUI-DSL"),
        L(T(f"""<p>Pages get their own language. A GUI-DSL model describes one page as a tree: a page holds cards, a card has a head and a body, the body holds tables, buttons, labels {cite('GMNR21')}. And it refers into the class diagram by name — the symbol table at work. This is a whole page model, slightly simplified — in MaCoCo, a page usually gets its data through a separate view-model class:</p>""",
              f"""<p>Seiten bekommen eine eigene Sprache. Ein GUI-DSL-Modell beschreibt eine Seite als Baum: Eine Seite enthält Karten, eine Karte hat Kopf und Rumpf, der Rumpf enthält Tabellen, Knöpfe, Beschriftungen {cite('GMNR21')}. Und es verweist über Namen in das Klassendiagramm — die Symboltabelle bei der Arbeit. Das ist ein ganzes Seitenmodell, leicht vereinfacht — in MaCoCo bekommt eine Seite ihre Daten meist über eine eigene View-Model-Klasse:</p>"""))
        + '<pre class="mono art-pre">webpage Books(all Book b) {\n  card {\n    head { label "Books" }\n    body {\n      datatable { rows &lt;b {\n        column "Title", title\n        column "Pages", pages\n}}}}}</pre>'
        + L(T("<p><code>all Book b</code> loads all books; <code>rows &lt;b</code> makes one table row per book; <code>column \"Title\", title</code> shows the attribute <code>title</code> from the class diagram. Data, page and rules, each in its own language, end up on one screen:</p>",
              "<p><code>all Book b</code> lädt alle Bücher; <code>rows &lt;b</code> macht eine Tabellenzeile pro Buch; <code>column \"Title\", title</code> zeigt das Attribut <code>title</code> aus dem Klassendiagramm. Daten, Seite und Regeln, jede in ihrer eigenen Sprache, landen auf einem Bildschirm:</p>"))
        + fig_three_languages(lang)
        + L(T(f"""<p>One piece of advice from practice: do not bury large amounts of hand-written HTML inside page models — they become as hard to read as the HTML itself; keep highly specific parts entirely hand-written {cite('BGK+24')}.</p>""",
              f"""<p>Ein Rat aus der Praxis: Keine großen Mengen handgeschriebenes HTML in Seitenmodellen vergraben — sie werden dann so schwer lesbar wie das HTML selbst; sehr spezielle Teile schreibt man besser ganz von Hand {cite('BGK+24')}.</p>"""))))
    S.append(("cd2gui", 3, T("CD2GUI: from a class diagram to an application", "CD2GUI: vom Klassendiagramm zur Anwendung"),
        L(T(f"""<p>Page models still have to be written. CD2GUI removes even that step: from one class diagram it derives the page models by itself. Its output is not code but more models — a <i>model-to-model transformation</i> — which MontiGem then turns into code as if someone had written them by hand. For every class there is an <i>overview</i> page (all objects in a table) and a <i>details</i> page (one object with its attributes and associations), plus one dashboard for all classes {cite('GMN+20')}.</p>""",
              f"""<p>Seitenmodelle müssen immer noch geschrieben werden. CD2GUI nimmt auch diesen Schritt ab: Aus einem Klassendiagramm leitet es die Seitenmodelle selbst ab. Sein Ergebnis ist kein Code, sondern wieder Modelle — eine <i>Modell-zu-Modell-Transformation</i> —, die MontiGem dann zu Code macht, als hätte sie jemand von Hand geschrieben. Für jede Klasse gibt es eine <i>Übersichtsseite</i> (alle Objekte in einer Tabelle) und eine <i>Detailseite</i> (ein Objekt mit Attributen und Assoziationen), dazu ein Dashboard für alle Klassen {cite('GMN+20')}.</p>"""))
        + definition(T("Model transformation", "Modelltransformation"), T(f"A model transformation applies to one or more source models and transforms them into one or more target models. {ref(DEF)}",
                                                                          f"Eine Modelltransformation wird auf ein oder mehrere Quellmodelle angewendet und überführt sie in ein oder mehrere Zielmodelle. {ref(DEF)}"), lang)
        + demo_cd2gui(lang)
        + L(T("""<p>And when the library wants something else on the member page — two buttons, for a new loan and a reminder? Not in the generated HTML: in a small hand-written <i>delta model</i> with operations such as <code>remove</code>, <code>replace</code>, <code>add_to</code>, <code>add_before</code> and <code>add_after</code>, applied to the generated page tree before code is generated. That is the answer to TOP’s limit: since the change lives in a model, it survives every regeneration. Which components the pages get is decided by simple rules:</p>""",
              """<p>Und wenn die Bibliothek auf der Mitgliederseite etwas anderes will — zwei Knöpfe, für eine neue Ausleihe und eine Erinnerung? Nicht im generierten HTML: in einem kleinen handgeschriebenen <i>Delta-Modell</i> mit Operationen wie <code>remove</code>, <code>replace</code>, <code>add_to</code>, <code>add_before</code> und <code>add_after</code>, das auf den generierten Seitenbaum angewendet wird, bevor Code entsteht. Das ist die Antwort auf die Grenze von TOP: Weil die Änderung in einem Modell steckt, übersteht sie jede Neugenerierung. Welche Bausteine die Seiten bekommen, entscheiden einfache Regeln:</p>"""))
        + mapping_table(lang)
        + L(T(f"""<p>The concept appeared in 2020; its first use in a real project was the digital-twin cockpits for wind turbines {cite('MNN+22')} — see the <a href="projects-add.html">ADD project</a>. A generated application can be clicked through online:</p>""",
              f"""<p>Das Konzept erschien 2020; zum ersten Mal in einem echten Projekt eingesetzt wurde es bei den Digital-Twin-Cockpits für Windkraftanlagen {cite('MNN+22')} — siehe das <a href="projects-add.html">ADD-Projekt</a>. Eine generierte Anwendung lässt sich online durchklicken:</p>"""))
        + tries(lang, [("MontiGem demo", DEMO, T("a generated application", "eine generierte Anwendung"))])))
    S.append(("grow", 3, T("When requirements change: titles and copies", "Wenn sich Anforderungen ändern: Titel und Exemplare"),
        L(T("""<p>A generated application is a start, not the end. Say the library finds that <code>Book</code> mixes two things: the title in the catalogue and the physical copies on the shelf. Copies must be tracked one by one, and no copy may be lent twice at the same time. The model changes — <code>available</code> moves to a new class <code>BookCopy</code>, and a loan now points to a copy:</p>""",
              """<p>Eine generierte Anwendung ist ein Anfang, nicht das Ende. Angenommen, die Bibliothek merkt, dass <code>Book</code> zwei Dinge vermischt: den Titel im Katalog und die Exemplare im Regal. Exemplare sollen einzeln verfolgt werden, und kein Exemplar darf zweimal gleichzeitig verliehen sein. Das Modell ändert sich — <code>available</code> wandert in eine neue Klasse <code>BookCopy</code>, und eine Ausleihe verweist jetzt auf ein Exemplar:</p>"""))
        + '<pre class="mono art-pre">classdiagram Library {\n  class Book { String title; int pages; }\n  class BookCopy { boolean available; }\n  class Member { String name; }\n  class Loan { Date due; }\n  association [1] Book -> (copies) BookCopy [*];\n  association [1] Member -> (loans) Loan [*];\n  association [*] Loan -> (copy) BookCopy [1];\n}</pre>'
        + L(T("""<p>Regenerating brings the tables, server classes and transfer objects for copies and, through CD2GUI, their overview and details pages, with each book’s copies on its details page. Three things it does not bring. The rule “one open loan per copy” is not in a class diagram: it needs an OCL/P invariant or a hand-written check — and a way to tell open loans from returned ones, which the model does not have yet. The lending workflow — check out, return, remind — is hand-written code or further models on top of the generated pages. And the loans already stored point to books, not copies: a migration has to create the copies and re-link the loans. Nothing is thrown away, though: the application is regenerated around the new model, and only the hand-written parts that touched a book’s availability need adapting.</p>""",
              """<p>Neu generieren bringt die Tabellen, Serverklassen und Transferobjekte für Exemplare und, über CD2GUI, ihre Übersichts- und Detailseiten, mit den Exemplaren eines Buchs auf dessen Detailseite. Drei Dinge bringt es nicht. Die Regel „eine offene Ausleihe pro Exemplar“ steht in keinem Klassendiagramm: Sie braucht eine OCL/P-Invariante oder eine handgeschriebene Prüfung — und eine Möglichkeit, offene von zurückgegebenen Ausleihen zu unterscheiden, die das Modell noch nicht hat. Der Ausleihablauf — ausleihen, zurückgeben, erinnern — ist handgeschriebener Code oder weitere Modelle über den generierten Seiten. Und die schon gespeicherten Ausleihen verweisen auf Bücher, nicht auf Exemplare: Eine Migration muss die Exemplare anlegen und die Ausleihen neu verknüpfen. Weggeworfen wird trotzdem nichts: Die Anwendung wird um das neue Modell herum neu generiert, und nur die handgeschriebenen Teile, die die Verfügbarkeit eines Buchs berührten, müssen angepasst werden.</p>"""))))
    S.append(("lowcode", 3, T("Where this leads: low-code and AI", "Wohin das führt: Low-Code und KI"),
        L(T(f"""<span id="ai"></span><p>Low-code platforms promise applications without programming. Seen from MDE, many of them are a familiar recipe: a modelling language behind the wizards, plus ready-made building blocks and a platform that runs the result — even when the language is never named {ref(LC)}. The form designer is a page model, the data source is a class diagram. Platforms differ in what they do with the models: some generate code, as MontiGem does; others interpret the models while the application runs. Both are model-driven.</p>
<p>Will business people now write their software themselves? The same was promised for COBOL {ref(FDSL)}, and low-code languages tend to grow back into fuller languages over time. The realistic role for citizen developers is that of co-authors of models — which is what this article is meant to prepare for.</p>""",
              f"""<span id="ai"></span><p>Low-Code-Plattformen versprechen Anwendungen ohne Programmierung. Aus Sicht von MDE sind viele von ihnen ein bekanntes Rezept: eine Modellierungssprache hinter den Assistenten, dazu fertige Bausteine und eine Plattform, die das Ergebnis ausführt — auch wenn die Sprache nie beim Namen genannt wird {ref(LC)}. Der Formular-Designer ist ein Seitenmodell, die Datenquelle ist ein Klassendiagramm. Die Plattformen unterscheiden sich darin, was sie mit den Modellen tun: Manche generieren Code, wie MontiGem; andere interpretieren die Modelle, während die Anwendung läuft. Beides ist modellgetrieben.</p>
<p>Schreiben Fachleute ihre Software jetzt selbst? Dasselbe wurde für COBOL versprochen {ref(FDSL)}, und Low-Code-Sprachen wachsen mit der Zeit gern zu vollständigeren Sprachen zurück. Die realistische Rolle für Citizen Developer ist die von Mitautorinnen der Modelle — und darauf soll dieser Artikel vorbereiten.</p>"""))
        + L(T(f"""<p>And then there is AI. Writing the model is the step that still takes expertise — and it is the one an LLM can help with: describe the domain in a sentence, the LLM writes the class diagram, and CD2GUI and MontiGem do the rest, deterministically. In our 2024 experiments, GPT-4 asked for a CD4A model without any context wrote no valid one in 20 tries. A predefined conversation that explained the key rules of the language raised this to 99 of 100 for one task; giving examples instead reached 88 of 100 {cite('NMR24')}. “Valid” means the CD4A parser accepted the model — whether it describes the right domain is a separate question that the parser cannot answer; it stays with the domain expert.</p>""",
              f"""<p>Und dann ist da KI. Das Modell zu schreiben ist der Schritt, der noch Fachwissen braucht — und genau dabei kann ein LLM helfen: die Domäne in einem Satz beschreiben, das LLM schreibt das Klassendiagramm, und CD2GUI und MontiGem machen den Rest, deterministisch. In unseren Experimenten von 2024 schrieb GPT-4, ohne jeden Kontext nach einem CD4A-Modell gefragt, in 20 Versuchen kein gültiges. Ein vorgegebenes Gespräch, das die wichtigsten Regeln der Sprache erklärte, hob das bei einer Aufgabe auf 99 von 100; Beispiele statt Erklärungen erreichten 88 von 100 {cite('NMR24')}. „Gültig“ heißt, dass der CD4A-Parser das Modell angenommen hat — ob es die richtige Domäne beschreibt, ist eine andere Frage, die der Parser nicht beantworten kann; sie bleibt bei der Fachexpertin.</p>"""))
        + fig_chain(lang)
        + L(T('<p>How an LLM works, how it learns a modelling language and how a grammar keeps it from writing invalid models is the subject of <a href="research-ai4se.html">part 2 of this series: AI-driven software engineering</a> — continue with <a href="research-ai4se.html#models">language models that write models</a>.</p>',
              '<p>Wie ein LLM funktioniert, wie es eine Modellierungssprache lernt und wie eine Grammatik es davon abhält, ungültige Modelle zu schreiben, ist Thema von <a href="research-ai4se.html">Teil 2 dieser Reihe: KI-getriebene Softwareentwicklung</a> — weiter mit <a href="research-ai4se.html#models">Sprachmodelle, die Modelle schreiben</a>.</p>'))))
    S.append(("practice", 3, T("Case study: MaCoCo and four other domains", "Fallstudie: MaCoCo und vier weitere Domänen"),
        L(T(f"""<p>MontiGem did not start on a whiteboard but in a running system. <a href="projects-macoco.html">MaCoCo</a>, the management cockpit RWTH chairs use for their finances, staff and projects, began as a hand-written application; generation was added to it one aspect at a time, following a method of 16 activities {cite('DGM+21')}.</p>
<p>MaCoCo in numbers {cite('GLM+24')} — code and models as of March 2022, users at the time of the report:</p>""",
              f"""<p>MontiGem entstand nicht am Whiteboard, sondern in einem laufenden System. <a href="projects-macoco.html">MaCoCo</a>, das Management-Cockpit, mit dem Lehrstühle der RWTH ihre Finanzen, ihr Personal und ihre Projekte verwalten, begann als handgeschriebene Anwendung; Generierung kam Aspekt für Aspekt hinzu, nach einer Methode mit 16 Aktivitäten {cite('DGM+21')}.</p>
<p>MaCoCo in Zahlen {cite('GLM+24')} — Code und Modelle mit Stand März 2022, Nutzer zum Zeitpunkt des Berichts:</p>"""))
        + stats(lang, [("74.59 %" if lang == "en" else "74,59 %", T("of the implementation code generated", "des Implementierungscodes generiert")),
                       ("500,573" if lang == "en" else "500.573", T("generated lines", "generierte Zeilen")),
                       ("73 · 74", T("domain classes · GUI models", "Domänenklassen · GUI-Modelle")),
                       ("1,403" if lang == "en" else "1.403", T("users at 188 chairs and institutes", "Nutzer an 188 Lehrstühlen und Instituten"))])
        + L(T("""<p>The share compares lines of code: 500,573 generated against 170,505 hand-written; the 14,251 lines of models are not counted (with them, it would be about 73 %). It measures how much of the code is generated — not how much effort was saved. And it is not “generated instead of hand-written”: every page consists of generated base code that is extended and optimised by hand.</p>""",
              """<p>Der Anteil vergleicht Codezeilen: 500.573 generierte gegen 170.505 handgeschriebene; die 14.251 Zeilen Modelle zählen nicht mit (mit ihnen wären es etwa 73 %). Er misst, wie viel des Codes generiert ist — nicht, wie viel Aufwand gespart wurde. Und er heißt nicht „generiert statt handgeschrieben“: Jede Seite besteht aus generiertem Basiscode, der von Hand erweitert und optimiert wird.</p>"""))
        + fig_retrofit(lang)
        + L(T(f"""<p>After about three years, the generator was extracted from MaCoCo into a framework of its own, MontiGem, and used in four more domains {cite('BGK+24')}: tool tracking for craftsmen with <a href="projects-ford.html">Ford</a>, energy management of buildings, the privacy policies of wearables (InviDas), and the engineering of wind turbines (<a href="projects-add.html">ADD</a>). What the five projects taught is summed up below, under <a href="#costs">what it costs</a> and <a href="#summary">when this approach pays off</a>; more on the <a href="projects-montigem.html">MontiGem project page</a>.</p>""",
              f"""<p>Nach etwa drei Jahren wurde der Generator aus MaCoCo in ein eigenes Framework herausgelöst, MontiGem, und in vier weiteren Domänen eingesetzt {cite('BGK+24')}: Werkzeugverfolgung für Handwerksbetriebe mit <a href="projects-ford.html">Ford</a>, Energiemanagement von Gebäuden, die Datenschutzerklärungen von Wearables (InviDas) und die Entwicklung von Windkraftanlagen (<a href="projects-add.html">ADD</a>). Was die fünf Projekte gelehrt haben, steht unten unter <a href="#costs">Was es kostet</a> und <a href="#summary">Wann sich dieser Ansatz lohnt</a>; mehr auf der <a href="projects-montigem.html">MontiGem-Projektseite</a>.</p>"""))))
    S.append(("costs", 3, T("What it costs", "Was es kostet"),
        L(T(f"""<p>None of this comes free. The costs are engineering trade-offs, and the five MontiGem projects show where they lie {cite('BGK+24')}:</p>
<ul class="pts"><li><b>An investment up front.</b> Languages, generators, templates and the runtime environment have to be built before they pay off — which is why reusing them across projects matters. Retrofitting a generator into a running system is harder still, but paid off in the long run.</li><li><b>Two things to maintain.</b> Models and generator evolve together: every project brought new patterns that had to go into the tooling.</li><li><b>Debugging across layers.</b> An error can sit in the model, a transformation, a template, the generated code or the runtime. In the projects this stayed manageable as long as the mapping from model to code was straightforward.</li><li><b>Extension boundaries.</b> Generated parts have to be replaceable where they meet existing systems, and very specific screens are better written entirely by hand.</li><li><b>Expertise.</b> Someone has to model well and someone has to maintain the languages; all five projects had MDE experts on board.</li></ul>""",
              f"""<p>Nichts davon gibt es umsonst. Die Kosten sind technische Abwägungen, und die fünf MontiGem-Projekte zeigen, wo sie liegen {cite('BGK+24')}:</p>
<ul class="pts"><li><b>Eine Vorleistung.</b> Sprachen, Generatoren, Templates und Laufzeitumgebung müssen gebaut sein, bevor sie sich auszahlen — deshalb zählt ihre Wiederverwendung über Projekte hinweg. Einen Generator in ein laufendes System nachzurüsten ist noch schwerer, hat sich aber langfristig gelohnt.</li><li><b>Zwei Dinge zu pflegen.</b> Modelle und Generator entwickeln sich gemeinsam: Jedes Projekt brachte neue Muster, die ins Werkzeug mussten.</li><li><b>Fehlersuche über Schichten.</b> Ein Fehler kann im Modell, in einer Transformation, einem Template, im generierten Code oder in der Laufzeitumgebung stecken. In den Projekten blieb das beherrschbar, solange die Abbildung vom Modell auf den Code geradlinig war.</li><li><b>Grenzen der Erweiterung.</b> Generierte Teile müssen ersetzbar sein, wo sie auf bestehende Systeme treffen, und sehr spezielle Masken schreibt man besser ganz von Hand.</li><li><b>Fachwissen.</b> Jemand muss gut modellieren und jemand die Sprachen pflegen können; in allen fünf Projekten waren MDE-Fachleute dabei.</li></ul>"""))))
    S.append(("summary", 1, T("In short", "Kurz gesagt"),
        L(T("""<ul class="pts"><li><b>A model</b> is a purposeful simplification of an original: ask what it is for, not whether it is complete.</li><li><b>The picture is not the model:</b> behind text and diagram sits a structure that tools can check (in MontiCore, a tree) — and “it parses” is not “it is correct”.</li><li><b>A DSL</b> gives up generality to get close to one domain; you already use several.</li><li><b>A generator</b> works like mail merge for code and carries architectural decisions: one model line becomes consistent code in every tier.</li><li><b>Generated and hand-written code are kept apart</b>, so you can regenerate at any time — the value lies in repeated generation, not in a one-shot scaffold.</li><li><b>CD2GUI and MontiGem</b> turn one class diagram into a running, data-centric prototype that grows into a full-size system without being thrown away.</li><li><b>Many low-code platforms are MDE</b> with a platform and a friendlier surface; AI fits in front of it: the LLM writes only the model, and a deterministic, testable generator does the rest.</li></ul><p>The central benefit is not that models can generate code. It is that domain decisions stay explicit, checkable and reusable for the whole life of a system: when models, generators and hand-written extensions evolve together, a first prototype can grow into a full-size application without abandoning its models.</p>""",
              """<ul class="pts"><li><b>Ein Modell</b> ist eine zweckgerichtete Vereinfachung eines Originals: Fragen Sie, wofür es da ist, nicht ob es vollständig ist.</li><li><b>Das Bild ist nicht das Modell:</b> Hinter Text und Diagramm steht eine Struktur, die Werkzeuge prüfen können (in MontiCore ein Baum) — und „es parst“ heißt nicht „es ist richtig“.</li><li><b>Eine DSL</b> verzichtet auf Allgemeinheit, um nah an einer Domäne zu sein; einige benutzen Sie schon.</li><li><b>Ein Generator</b> arbeitet wie ein Serienbrief für Code und trägt Architekturentscheidungen: Eine Modellzeile wird zu stimmigem Code in jeder Schicht.</li><li><b>Generierter und handgeschriebener Code bleiben getrennt</b>, damit jederzeit neu generiert werden kann — der Wert liegt im wiederholten Generieren, nicht in einem einmaligen Gerüst.</li><li><b>CD2GUI und MontiGem</b> machen aus einem Klassendiagramm einen laufenden, datenzentrierten Prototyp, der zum vollwertigen System wächst, ohne weggeworfen zu werden.</li><li><b>Viele Low-Code-Plattformen sind MDE</b> mit einer Plattform und einer freundlicheren Oberfläche; KI passt davor: Das LLM schreibt nur das Modell, ein deterministischer, testbarer Generator macht den Rest.</li></ul><p>Der zentrale Gewinn ist nicht, dass Modelle Code erzeugen können. Er ist, dass fachliche Entscheidungen über das ganze Leben eines Systems explizit, prüfbar und wiederverwendbar bleiben: Wenn Modelle, Generatoren und handgeschriebene Erweiterungen sich gemeinsam entwickeln, kann ein erster Prototyp zur vollwertigen Anwendung wachsen, ohne seine Modelle aufzugeben.</p>"""))
        + L(T(f"""<div class="fit"><div><span class="k mono">WORTH IT WHEN</span><ul class="pts"><li>the application is data-centric and built around CRUD</li><li>stakeholders should click through early prototypes — they show problems with requirements and data structures very early</li><li>the team has examples and documentation: learning to model does not take long, even for untrained students</li></ul></div>
<div><span class="k mono">SOMETHING ELSE IS ENOUGH WHEN</span><ul class="pts"><li>customers want very specific screens — generated pages were great for prototypes, not for such requirements</li><li>the user experience is unusual; native apps did better there</li><li>nobody on the team can model well: the result is only as good as the data model</li></ul></div></div>
<p class="fit-src mono">What five projects with MontiGem taught {cite('BGK+24')}.</p>""",
              f"""<div class="fit"><div><span class="k mono">LOHNT SICH, WENN</span><ul class="pts"><li>die Anwendung datenzentriert ist und sich um CRUD dreht</li><li>Beteiligte sich früh durch Prototypen klicken sollen — die zeigen Probleme in Anforderungen und Datenstrukturen sehr früh</li><li>das Team Beispiele und Dokumentation hat: Modellieren zu lernen dauert nicht lange, selbst für ungeübte Studierende</li></ul></div>
<div><span class="k mono">ETWAS ANDERES REICHT, WENN</span><ul class="pts"><li>Kunden sehr spezielle Masken wollen — generierte Seiten waren großartig für Prototypen, nicht für solche Anforderungen</li><li>die Bedienung ungewöhnlich ist; native Apps waren dort besser</li><li>niemand im Team gut modellieren kann: Das Ergebnis ist nur so gut wie das Datenmodell</li></ul></div></div>
<p class="fit-src mono">Was fünf Projekte mit MontiGem gelehrt haben {cite('BGK+24')}.</p>"""))
        + L(T(f'<div class="tryit"><span class="k mono">TRY IT IN 10 MINUTES</span><ol><li>Describe your domain to the <a href="{CD4A_GPT[1]}" target="_blank" rel="noopener">CD4A Class Diagram Creator ↗</a>.</li><li>Read the result with <a href="#classdiagram">the 60-second guide</a> above.</li><li>Open the <a href="{DEMO}" target="_blank" rel="noopener">MontiGem demo ↗</a> to see what such a model becomes.</li></ol></div>',
              f'<div class="tryit"><span class="k mono">IN 10 MINUTEN AUSPROBIEREN</span><ol><li>Beschreiben Sie Ihre Domäne dem <a href="{CD4A_GPT[1]}" target="_blank" rel="noopener">CD4A Class Diagram Creator ↗</a>.</li><li>Lesen Sie das Ergebnis mit der <a href="#classdiagram">60-Sekunden-Anleitung</a> oben.</li><li>Öffnen Sie die <a href="{DEMO}" target="_blank" rel="noopener">MontiGem-Demo ↗</a> und sehen Sie, was aus so einem Modell wird.</li></ol></div>'))))
    refs = "".join(f'<li id="ref-{k}">{r}</li>' for k, r in enumerate(REFS, 1))
    # short side-nav labels for the long headings (as in EA)
    NAV = {"classdiagram": T("Class diagrams", "Klassendiagramme"), "dsl": T("DSLs", "DSLs"),
           "syntax": T("Picture vs model", "Bild vs. Modell"), "handwritten": T("Hand-written code", "Handgeschriebener Code"),
           "montigem": T("Whole applications", "Ganze Anwendungen"), "whygen": T("Repetition", "Wiederholung"),
           "guidsl": T("GUI-DSL", "GUI-DSL"), "cd2gui": T("CD2GUI", "CD2GUI"), "lowcode": T("Low-code and AI", "Low-Code und KI"), "grow": T("Titles and copies", "Titel und Exemplare"),
           "practice": T("Case: MaCoCo", "Fall: MaCoCo")}
    S = [it + (NAV[it[0]],) if it[0] in NAV and len(it) == 4 else it for it in S]
    return article_common.sections(S, lang), refs


def page(lang):
    """Returns (file, title, description, body, scripts) for build.py; header, literature and series end come from
    article_common (the same for all four parts)."""
    sections, refs = body(lang)
    lead = T("Software from <em>models</em>: what DSLs, models and generators are — and how one class diagram becomes a running web application.",
             "Software aus <em>Modellen</em>: was DSLs, Modelle und Generatoren sind — und wie aus einem Klassendiagramm eine laufende Webanwendung wird.")
    desc = T("Model-driven software engineering: what models, DSLs and generators are, and how MontiGem and CD2GUI turn one class diagram into a web application — an article by Lukas Netz.",
             "Modellgetriebene Softwareentwicklung: was Modelle, DSLs und Generatoren sind und wie MontiGem und CD2GUI aus einem Klassendiagramm eine Webanwendung machen — ein Artikel von Lukas Netz.")
    return article_common.page(lang, FILE, sections, refs, OWN, hero_mde(lang), lead, desc,
                               article_common.scripts(lang, "mde", css=True))
